import{t as e}from"./i18n-BACIlDIj.js";import{t}from"./calendar-DdCdNFRS.js";import{t as n}from"./dice-B2oG8VHA.js";import{i as r,n as i,r as a,t as o}from"./audio-DJlMO-LG.js";import{i as s,u as c}from"./calendar-BLTdHR4R.js";/* empty css               */import{n as l}from"./series-bag-CAUNANgy.js";var u={title:{no:`Potetåkeren`,en:`The potato plot`},place:{no:`Mäkelä gård, Lista`,en:`Mäkelä farm, Lista`},week:{no:`Uke {n} av {max}`,en:`Week {n} of {max}`},trips:{no:`Turer igjen: {n}`,en:`Trips left: {n}`},favours:{no:`Tjenester fra Eeli: {n}`,en:`Favours from Eeli: {n}`},weeksLeft:{no:`Uker til pløying: {n}`,en:`Weeks to ploughing: {n}`},lastTripNow:{no:`Dette er siste tur i år. Det som står igjen når Anntu pløyer, tar Eeli opp med maskin.`,en:`This is your last trip this year. Eeli lifts what is left by machine when Anntu ploughs.`},howTitle:{no:`Slik går sesongen`,en:`How the season goes`},howTrips:{no:`Du har {trips} turer til Lista på {weeks} uker. Mellom turene går ukene av seg selv, så spar noen til sommeren og høsten.`,en:`You have {trips} trips to Lista in {weeks} weeks. Between trips the weeks pass on their own, so save some for summer and autumn.`},howBlocks:{no:`På hver tur rekker du {n} ting. En ting er ett redskap brukt på én rad.`,en:`On each trip you have time for {n} things. A thing is one tool used on one row.`},howFavours:{no:`Eeli sender melding når noe skjer mens du er hjemme. Han kan gjøre jobben for deg {n} ganger.`,en:`Eeli texts when something is up while you are home. He can do the job for you {n} times.`},visited:{no:`du var her`,en:`you were here`},soundOn:{no:`Lyd på`,en:`Sound on`},soundOff:{no:`Lyd av`,en:`Sound off`},calendar:{no:`Sesongen`,en:`The season`},now:{no:`nå`,en:`now`},midsummer:{no:`Sankthans`,en:`Midsummer`},plough:{no:`Anntu pløyer`,en:`Anntu ploughs`},forecast:{no:`Varselet`,en:`The forecast`},forecastNext:{no:`Uka som kommer: {sky}`,en:`The coming week: {sky}`},forecastAfter:{no:`Uka etter: {sky} (usikkert)`,en:`The week after: {sky} (unsure)`},frostRisk:{no:`fare for nattefrost`,en:`risk of night frost`},field:{no:`Teigen din`,en:`Your plot`},row:{no:`Rad {n}`,en:`Row {n}`},slot:{no:`Rad {row}, plass {slot}`,en:`Row {row}, place {slot}`},tools:{no:`Redskap`,en:`Tools`},time:{no:`Du rekker {n} ting til i dag`,en:`You have time for {n} more things today`},timeOne:{no:`Du rekker 1 ting til i dag`,en:`You have time for 1 more thing today`},timeNone:{no:`Du rekker ikke mer i dag. Prøvegraving og å ta av duk går alltid.`,en:`No time for more today. A test dig and taking a fleece off are always possible.`},pickTool:{no:`Velg et redskap, og trykk på en rad.`,en:`Pick a tool, then tap a row.`},pickSeed:{no:`Trykk der settepotetene skal ligge.`,en:`Tap where the seed potatoes go.`},pickDig:{no:`Trykk på planten du vil grave opp.`,en:`Tap the plant you want to dig up.`},barn:{no:`Låven`,en:`The barn`},barnEmpty:{no:`Ingen kasser ennå.`,en:`No crates yet.`},crate:{no:`Kasse {n}: {variety} fra rad {row}`,en:`Crate {n}: {variety} from row {row}`},basket:{no:`Kurv: {variety} fra rad {row} (prøvegravd)`,en:`Basket: {variety} from row {row} (test dig)`},byEeli:{no:`Tatt opp av Eeli med maskin`,en:`Lifted by Eeli by machine`},crateKg:{no:`{kg} kg, {n} poteter`,en:`{kg} kg, {n} potatoes`},crateEmpty:{no:`Ingen knoller ennå.`,en:`No tubers yet.`},cratePrime:{no:`Chipsstørrelse uten feil: {kg} kg`,en:`Crisping size, no flaws: {kg} kg`},crateBiggest:{no:`Største: {g} g`,en:`Biggest: {g} g`},skinThin:{no:`Skallet flasser: nypotet`,en:`The skin flakes: new potato`},skinSet:{no:`Skallet sitter: holder seg på lager`,en:`The skin has set: keeps in store`},flaws:{no:`Feil: {list}`,en:`Flaws: {list}`},flawRot:{no:`råte {kg} kg`,en:`rot {kg} kg`},flawGreen:{no:`grønne {kg} kg`,en:`green {kg} kg`},flawCrack:{no:`sprukne {kg} kg`,en:`cracked {kg} kg`},flawScab:{no:`skurv {kg} kg`,en:`scab {kg} kg`},giveTo:{no:`Gi til {who}`,en:`Give to {who}`},toCellar:{no:`Sett i kjelleren`,en:`Put in the cellar`},takeBack:{no:`Ta tilbake`,en:`Take back`},givenTo:{no:`Gitt til {who}`,en:`Given to {who}`},inCellar:{no:`Står i kjelleren`,en:`In the cellar`},wishes:{no:`Ønskelista`,en:`The wish list`},goalsJump:{no:`Ønskelista: trykk for å se hele`,en:`The wish list: tap to see all of it`},askAnntu:{no:`Hva sier Anntu?`,en:`What does Anntu say?`},askedAnntu:{no:`Anntu har sagt sitt i dag`,en:`Anntu has said her piece today`},pickVariety:{no:`Velg en sort først.`,en:`Pick a variety first.`},unniHas:{no:`{kg} av {max} kg`,en:`{kg} of {max} kg`},unniLate:{no:`Sankthans er over`,en:`Midsummer has passed`},siriHas:{no:`{kg} av {max} kg. Steker: {fry}`,en:`{kg} of {max} kg. Fries: {fry}`},siriNone:{no:`Ingen kasse ennå`,en:`No crate yet`},einarHas:{no:`Største hittil: {g} g`,en:`Biggest so far: {g} g`},einarNone:{no:`Ingen potet ennå`,en:`No potato yet`},fryTest:{no:`Prøvesteking`,en:`Test fry`},dm:{no:`Tørrstoff {dm} %`,en:`Dry matter {dm} %`},goHome:{no:`Reis hjem`,en:`Go home`},comeBack:{no:`Når kommer du tilbake?`,en:`When do you come back?`},comeBackNote:{no:`Ukene går av seg selv til du kommer tilbake. Eeli sier fra hvis noe skjer.`,en:`The weeks pass on their own until you come back. Eeli will text if something is up.`},pace:{no:`{trips} turer igjen, og {weeks} uker til Anntu pløyer. Skal turene vare, kan du komme omtrent hver {every}. uke.`,en:`{trips} trips left, and {weeks} weeks until Anntu ploughs. To make them last, come about every {every} weeks.`},paceOne:{no:`1 tur igjen, og {weeks} uker til Anntu pløyer. Velg uka med omhu.`,en:`1 trip left, and {weeks} weeks until Anntu ploughs. Pick the week with care.`},letRunNote:{no:`Da kommer du ikke tilbake før Eeli sender melding. Turene dine har du fortsatt.`,en:`Then you do not come back until Eeli texts. You still have your trips.`},alertNote:{no:`Eeli gjør bare den ene jobben, på sin måte. Kommer du selv, rekker du {n} ting. Lar du det stå, går uka uten at noe blir gjort.`,en:`Eeli does just that one job, his way. If you come yourself, you have time for {n} things. If you leave it, the week passes with nothing done.`},handout:{no:`Del ut kassene`,en:`Hand out the crates`},inWeeks:{no:`Om {n} uker`,en:`In {n} weeks`},inOneWeek:{no:`Om 1 uke`,en:`In 1 week`},lastTrip:{no:`Dette var siste tur. Resten av sesongen går uten deg.`,en:`This was your last trip. The rest of the season goes on without you.`},letRun:{no:`La sesongen gå`,en:`Let the season run`},lastWeek:{no:`Anntu pløyer neste uke. Det som står igjen, tar Eeli opp med maskin.`,en:`Anntu ploughs next week. Eeli lifts what is left by machine.`},endSeason:{no:`Avslutt sesongen`,en:`End the season`},stay:{no:`Bli litt til`,en:`Stay a little longer`},away:{no:`Hjemme i Kristiansand`,en:`At home in Kristiansand`},awayWeek:{no:`Uka som starter {date}`,en:`The week starting {date}`},eeliTexts:{no:`Melding fra Eeli`,en:`Text from Eeli`},yesEeli:{no:`Ja takk, Eeli (1 tjeneste)`,en:`Yes please, Eeli (1 favour)`},come:{no:`Jeg kommer selv (1 tur)`,en:`I will come myself (1 trip)`},wait:{no:`La det stå`,en:`Leave it`},rowsMeant:{no:`Gjelder: {rows}`,en:`About: {rows}`},since:{no:`Siden sist`,en:`Since last time`},sinceNothing:{no:`Det har ikke skjedd noe særlig.`,en:`Nothing much has happened.`},endTitle:{no:`Sesongen er over`,en:`The season is over`},endGive:{no:`Kassene står på låven. Ingen får poteter før du gir dem en kasse: velg under hver kasse. Det du ikke gir bort, går i kjelleren din.`,en:`The crates are in the barn. Nobody gets potatoes until you give them a crate: choose under each crate. What you do not give away goes to your cellar.`},seeHow:{no:`Se hvordan året gikk`,en:`See how the year went`},resultTitle:{no:`Slik gikk året`,en:`How the year went`},cellarTitle:{no:`Kjelleren din`,en:`Your cellar`},cellar:{no:`{kg} kg i kjelleren. {keeps} kg holder seg til jul.`,en:`{kg} kg in the cellar. {keeps} kg keep until Christmas.`},cellarNone:{no:`Kjelleren er tom i år.`,en:`The cellar is empty this year.`},rowsTitle:{no:`Radene dine`,en:`Your rows`},colVariety:{no:`Sort`,en:`Variety`},colPlanted:{no:`Satt`,en:`Planted`},colLifted:{no:`Tatt opp`,en:`Lifted`},colKg:{no:`Avling`,en:`Crop`},colPrime:{no:`Chipsstørrelse`,en:`Crisping size`},colFry:{no:`Steker`,en:`Fries`},colStory:{no:`Det som skjedde`,en:`What happened`},rowUnused:{no:`Ikke brukt`,en:`Not used`},rowNothing:{no:`Ingenting å ta opp`,en:`Nothing to lift`},rowEeli:{no:`Eeli, uke {n}`,en:`Eeli, week {n}`},weekN:{no:`uke {n}`,en:`week {n}`},bagTitle:{no:`Posen din`,en:`Your bag`},bagName:{no:`Navnet på posen`,en:`The name on the bag`},bagDefault:{no:`Mine egne`,en:`My own`},bagFrom:{no:`Potetgull fra egen åker, Lista`,en:`Crisps from my own plot, Lista`},sameYear:{no:`Samme vær en gang til`,en:`The same weather once more`},sameYearNote:{no:`Samme år, nye valg: da ser du hva valgene dine gjorde.`,en:`The same year, new choices: then you see what your choices did.`},newYear:{no:`Ny sesong, nytt vær`,en:`New season, new weather`},restart:{no:`Start sesongen på nytt`,en:`Start the season over`},and:{no:`og`,en:`and`}},d={seed:{icon:`🥔`,name:{no:`Sett`,en:`Plant`},short:{no:`Settepoteter i jorda`,en:`Seed potatoes in the soil`},what:{no:`Legg settepoteter der du vil i en tom rad. Én sort per rad. Tett gir mange små poteter, glissent gir få store.`,en:`Put seed potatoes where you like in an empty row. One variety to a row. Close gives many small potatoes, sparse gives few big ones.`}},water:{icon:`🚿`,name:{no:`Vann`,en:`Water`},short:{no:`Mot tørke`,en:`Against drought`},what:{no:`Fukter jorda i raden. I tørr jord vokser knollene lite, og de kan få skurv og sprekker.`,en:`Wets the soil in the row. In dry soil the tubers grow little, and they can get scab and cracks.`}},hill:{icon:`⛰️`,name:{no:`Hypp`,en:`Hill`},short:{no:`Mot grønne poteter og ugress`,en:`Against green potatoes, weeds`},what:{no:`Legger jord opp mot plantene. Da blir færre poteter grønne av lyset, og det meste av ugresset forsvinner. Går høyst to ganger, og bare før riset lukker raden.`,en:`Pulls soil up against the plants. Fewer potatoes turn green in the light, and most of the weeds go. At most twice, and only before the tops close the row.`}},weed:{icon:`🌾`,name:{no:`Luk`,en:`Weed`},short:{no:`Fjerner ugresset`,en:`Removes the weeds`},what:{no:`Fjerner alt ugresset i raden. Ugress tar vann og vekst fra potetene.`,en:`Removes all the weeds in the row. Weeds take water and growth from the potatoes.`}},fleece:{icon:`🧣`,name:{no:`Duk på/av`,en:`Fleece on/off`},short:{no:`Mot frost, gir varme`,en:`Against frost, gives warmth`},what:{no:`Duken verner spirene mot nattefrost og gir raskere vekst tidlig i sesongen, men ugresset trives under den. Du har 2 duker. Å ta av en duk koster ikke tid.`,en:`The fleece shields sprouts from night frost and speeds growth early on, but weeds thrive under it. You have 2 fleeces. Taking one off costs no time.`}},pick:{icon:`🍂`,name:{no:`Plukk blad`,en:`Pick leaves`},short:{no:`Bremser tørråte`,en:`Slows blight`},what:{no:`Plukker blad med brune flekker, så tørråten sprer seg saktere. Virker best mens flekkene er få.`,en:`Picks off leaves with brown spots, so blight spreads more slowly. Works best while the spots are few.`}},top:{icon:`✂️`,name:{no:`Ta riset`,en:`Cut the tops`},short:{no:`Stopper tørråte og vekst`,en:`Stops blight and growth`},what:{no:`Kutter riset i raden. Potetene slutter å vokse, men tørråten kommer ikke ned i knollene. Etter to uker sitter skallet, og potetene holder seg på lager.`,en:`Cuts the tops in the row. The potatoes stop growing, but blight cannot reach the tubers. After two weeks the skin has set, and the potatoes keep in store.`}},dig:{icon:`🔍`,name:{no:`Prøvegrav`,en:`Test dig`},short:{no:`Se under én plante`,en:`Look under one plant`},what:{no:`Graver opp én plante så du ser hvor store potetene er. Koster ikke tid, men planten er borte.`,en:`Digs up one plant so you see how big the potatoes are. Costs no time, but the plant is gone.`}},harvest:{icon:`🧺`,name:{no:`Ta opp`,en:`Lift`},short:{no:`Hele raden i en kasse`,en:`The whole row in a crate`},what:{no:`Tar opp hele raden i en kasse på låven. Tidlig gir små nypoteter. Venter du til riset har visna og skallet sitter, blir de større og holder seg.`,en:`Lifts the whole row into a crate in the barn. Early gives small new potatoes. If you wait until the tops have died back and the skin has set, they are bigger and keep.`}}},f={water:{no:`{row} er vanna. Jorda er fuktig igjen.`,en:`{row} is watered. The soil is moist again.`},hill:{no:`{row} er hyppet. Jorda ligger høyere rundt plantene.`,en:`{row} is hilled. The soil lies higher around the plants.`},weed:{no:`{row} er luket.`,en:`{row} is weeded.`},fleece:{no:`{row} har fått duk.`,en:`{row} is under a fleece.`},unfleece:{no:`{row}: duken er tatt av.`,en:`{row}: the fleece is off.`},pick:{no:`{row}: de syke bladene er plukket.`,en:`{row}: the sick leaves are picked.`},top:{no:`{row}: riset er kuttet. Vent to uker før du tar opp, så sitter skallet.`,en:`{row}: the tops are cut. Wait two weeks before you lift, and the skin will have set.`}},p={empty:{no:`Tom`,en:`Empty`},ground:{no:`I jorda`,en:`In the ground`},sprout:{no:`Spirer`,en:`Sprouting`},leafy:{no:`Vokser`,en:`Growing`},flower:{no:`Blomstrer`,en:`In flower`},bulk:{no:`Knollene vokser`,en:`Tubers growing`},ripe:{no:`Riset har visna`,en:`Tops have died back`},bare:{no:`Uten ris`,en:`No tops`},lifted:{no:`Tatt opp`,en:`Lifted`}},m={dry:{no:`Tørt`,en:`Dry`},soaked:{no:`Søkkvått`,en:`Soaked`},weeds1:{no:`Ugress`,en:`Weeds`},weeds2:{no:`Mye ugress`,en:`Lots of weeds`},blight1:{no:`Flekker på bladene`,en:`Spots on the leaves`},blight2:{no:`Tørråte`,en:`Blight`},blight3:{no:`Tørråten tok riset`,en:`Blight took the tops`},hilled1:{no:`Hyppet 1 gang`,en:`Hilled once`},hilled2:{no:`Hyppet 2 ganger`,en:`Hilled twice`},fleece:{no:`Under duk`,en:`Under fleece`}},h={away:{no:`Du er ikke på åkeren.`,en:`You are not at the plot.`},empty:{no:`Det står ingenting i den raden.`,en:`Nothing is planted in that row.`},lifted:{no:`Den raden er tatt opp.`,en:`That row has been lifted.`},no_time:{no:`Du rekker ikke mer i dag.`,en:`You have no time for more today.`},fleece_on:{no:`Ta av duken først.`,en:`Take the fleece off first.`},too_big:{no:`Riset er for stort til det nå.`,en:`The tops are too big for that now.`},hilled:{no:`Raden er hyppet to ganger. Mer jord er det ikke.`,en:`The row has been hilled twice. There is no more soil.`},hilled_now:{no:`Du har hyppet den raden i dag.`,en:`You have hilled that row today.`},no_weeds:{no:`Det er ikke ugress å luke der.`,en:`There are no weeds to pull there.`},no_fleece:{no:`Begge dukene er i bruk.`,en:`Both fleeces are in use.`},no_blight:{no:`Ingen syke blad å plukke der.`,en:`No sick leaves to pick there.`},no_tops:{no:`Det er ikke noe ris å ta.`,en:`There are no tops to cut.`},no_tubers:{no:`Det er ingen knoller der ennå.`,en:`There are no tubers there yet.`},no_plant:{no:`Det står ingen plante der.`,en:`There is no plant there.`},planted:{no:`Den raden er satt fra før.`,en:`That row is already planted.`},other_variety:{no:`Én sort per rad.`,en:`One variety to a row.`}},ee={dry:{icon:`☀️`,name:{no:`tørt`,en:`dry`}},mixed:{icon:`⛅`,name:{no:`litt av hvert`,en:`a bit of everything`}},wet:{icon:`🌧️`,name:{no:`vått`,en:`wet`}}},te={golden:{colour:`#e9b949`,name:{no:`gyllent`,en:`golden`}},dark:{colour:`#b6772c`,name:{no:`litt mørkt`,en:`a bit dark`}},brown:{colour:`#6f4522`,name:{no:`brunt`,en:`brown`}}},ne={up:{no:`har kommet opp`,en:`has come up`},frost:{no:`ble svidd av nattefrost`,en:`was bitten by night frost`},blight:{no:`har fått tørråte`,en:`has got blight`},dead:{no:`har mistet riset til tørråten`,en:`has lost its tops to blight`},dry:{no:`har stått tørt`,en:`has stood dry`},ripe:{no:`er moden: riset har visna`,en:`is ripe: the tops have died back`},fleece_blown:{no:`mistet duken i stormen`,en:`lost its fleece in the storm`},seedrot:{no:`mistet settepoteter i kald, våt jord`,en:`lost seed potatoes in cold, wet soil`}},re={frost:{no:`frost`,en:`frost`},dry:{no:`tørke`,en:`drought`},blight:{no:`tørråte`,en:`blight`},weeds:{no:`ugress`,en:`weeds`},seedrot:{no:`råtne settepoteter`,en:`rotted seed potatoes`},none:{no:`en rolig sesong`,en:`a quiet season`}},ie={frost:`❄️`,blight:`🍂`,dry:`🏜️`,ripe:`🧺`};function g(e,t={}){return e.replace(/\{(\w+)\}/g,(e,n)=>String(t[n]??`{${n}}`))}function ae(e,t,n={}){return g(u[e][t],n)}var oe=(e,t)=>t===`no`?String(e).replace(`.`,`,`):String(e);function se(e,t){return e.length<2?e.join(``):`${e.slice(0,-1).join(`, `)} ${u.and[t]} ${e[e.length-1]}`}var ce=`green`;function le(e,t){let n=e.trim()||u.bagDefault[t];return{name:n,colour:ce,front:[],label:`${n}. ${u.bagFrom[t]}`}}var ue={only:{season:[`spring`,`summer`,`autumn`]},weeks:28,trips:8,blocks:3,favours:3,rows:4,slots:8,fleeces:2,midsummer:11,varieties:[{id:`juno`,name:`Juno`,colour:`#e9d79a`,pace:1.3,yield:125,tubers:9,dm:18,sugar:.45,blight:.9,note:{no:`Tidlig. Liten avling, men først i jorda og først opp.`,en:`Early. A small crop, but first in the ground and first up.`}},{id:`lady_claire`,name:`Lady Claire`,colour:`#e3c877`,pace:1,yield:120,tubers:9,dm:24,sugar:.1,blight:.7,note:{no:`Chipspotet. Jevne, runde knoller som steker lyst.`,en:`A crisping potato. Even, round tubers that fry pale.`}},{id:`asterix`,name:`Asterix`,colour:`#c9705f`,pace:.88,yield:135,tubers:8,dm:21,sugar:.28,blight:.4,note:{no:`Rød og seig. Tåler tørråte bedre enn de andre.`,en:`Red and tough. Stands up to blight better than the others.`}},{id:`kerrs_pink`,name:`Kerrs Pink`,colour:`#e2a79a`,pace:.78,yield:150,tubers:7,dm:22,sugar:.4,blight:1,note:{no:`Sein og stor. Trenger hele sommeren, og tørråten liker den.`,en:`Late and big. Needs the whole summer, and blight likes it.`}}],wishes:{unni:{slug:`unni`,name:`Unni`,kg:2,ask:{no:`Nypoteter til sankthansfesten, vennen. Ei gryte holder. De må være oppe til sankthans.`,en:`New potatoes for the midsummer party, dear. One pot will do. They must be up by midsummer.`},short:{no:`{kg} kg nypoteter innen sankthans`,en:`{kg} kg of new potatoes by midsummer`},yes:{no:`Se på dem! Skallet går av med tommelen. Sett deg, så får du smake først.`,en:`Look at them! The skin rubs off with a thumb. Sit down, you get to taste first.`},more:{no:`Takk, vennen! Men det blir ikke ei hel gryte av det. Har du flere?`,en:`Thank you, dear! But that will not fill a pot. Have you got more?`},no:{no:`Det ble butikkpoteter i år, vennen. De smakte butikk.`,en:`It was shop potatoes this year, dear. They tasted of shop.`}},siri:{slug:`siri`,name:`Siri`,kg:5,ask:{no:`Ooh, egne poteter! Kom med fem kilo i chipsstørrelse, så prøvesteker jeg. Blir de gylne, får du pose med navnet ditt på.`,en:`Ooh, your own potatoes! Bring five kilos of crisping size and I will test-fry them. If they come out golden, you get a bag with your name on it.`},short:{no:`{kg} kg i chipsstørrelse som steker gyllent`,en:`{kg} kg of crisping size that fry golden`},golden:{no:`Gylne! Hør på det knaset. Den posen får navnet ditt, og jeg tar en neve selv.`,en:`Golden! Listen to that crunch. That bag gets your name, and I am having a handful myself.`},dark:{no:`Litt mørke i kanten. Gode til kaffen, men ikke til butikken. Sukkeret, vet du.`,en:`A bit dark at the edges. Fine with coffee, not for the shop. The sugar, you know.`},brown:{no:`Åh. Brune. For mye sukker i knollen. Det er jo et morsomt problem! Men ingen pose.`,en:`Oh. Brown. Too much sugar in the tuber. Now that is a fun problem! But no bag.`},soft:{no:`Fin farge, men de suger fett. For lite tørrstoff. Våte poteter gir bløte chips.`,en:`Nice colour, but they soak up oil. Too little dry matter. Wet potatoes make soft crisps.`},short_of:{no:`Det ble ikke nok i chipsstørrelse til en batch. Neste år!`,en:`There was not enough of crisping size for a batch. Next year!`},nothing:{no:`Ingen kasse til meg? Frityren sto klar og alt.`,en:`No crate for me? The fryer was ready and everything.`}},einar:{slug:`einar`,name:`Einar`,grams:600,near_grams:450,ask:{no:`Æ har vedda med Lars-Owe. Du skaffe en potet på over 600 gram. Itj spør ka æ vedda.`,en:`I have a bet with Lars-Owe. You get me a potato of over 600 grams. Do not ask what I bet.`},short:{no:`Én potet på over {grams} gram`,en:`One potato of over {grams} grams`},yes:{no:`{grams} gram! Æ visst det! Lars-Owe må spell på julebordet i potetkostyme.`,en:`{grams} grams! I knew it! Lars-Owe has to play the Christmas party in a potato costume.`},near:{no:`{grams} gram. Så nær! Vi sei at vekta i kantina vise feil.`,en:`{grams} grams. So close! We will say the canteen scale is off.`},no:{no:`{grams} gram? Da e det æ som må ha på potetkostymet. Det ordne sæ.`,en:`{grams} grams? Then I am the one in the potato costume. It will sort itself out.`},nothing:{no:`Ingen potet i det hele tatt? Æ må ha på potetkostymet. Det ordne sæ.`,en:`No potato at all? I am the one in the potato costume. It will sort itself out.`}}},anntu:{welcome:{no:`Teigen er din i år. Fire rader. Sett det du vil, der du vil. Poteten lyver ikke.`,en:`The plot is yours this year. Four rows. Plant what you like, where you like. The potato does not lie.`},first_seed:{no:`Tett gir mange og små. Glissent gir få og store. Du bestemmer.`,en:`Close gives many and small. Sparse gives few and big. You decide.`},first_water:{no:`Vann er bra. Jevnt vann er bedre.`,en:`Water is good. Even water is better.`},first_hill:{no:`Jord over knollene. Lys gjør dem grønne.`,en:`Soil over the tubers. Light turns them green.`},first_weed:{no:`Ugresset drikker først. Det har det alltid gjort.`,en:`The weeds drink first. They always have.`},first_fleece:{no:`Duken holder på varmen. Den skjuler ugresset også.`,en:`The fleece keeps the warmth in. It hides the weeds too.`},first_pick:{no:`Du rakk det. Denne gangen.`,en:`You caught it. This time.`},first_top:{no:`Uten ris vokser de ikke mer. Men råten kommer ikke ned til knollene.`,en:`With no tops they stop growing. But the rot cannot reach the tubers.`},first_dig:{no:`Nysgjerrig? Det koster en plante å se.`,en:`Curious? It costs a plant to look.`},harvest_unripe:{no:`Skallet flasser. Nypotet. God i dag, dårlig i kjelleren.`,en:`The skin flakes. New potato. Good today, poor in the cellar.`},harvest_good:{no:`Ikke så verst.`,en:`Not so bad.`},harvest_green:{no:`Grønne. De har sett sola. Hypp høyere neste år.`,en:`Green. They have seen the sun. Hill higher next year.`},harvest_rot:{no:`Råte. Den kom ned fra riset. Det var et hardt år for den raden.`,en:`Rot. It came down from the tops. It was a hard year for that row.`},harvest_scab:{no:`Skurv. De tørka da knollene ble satt.`,en:`Scab. They dried out when the tubers were set.`},harvest_crack:{no:`Sprekker. Tørt, så vått. Poteten liker det jevnt.`,en:`Cracks. Dry, then wet. The potato likes it even.`},year:{dry:{no:`Det var et tørt år. Den som vanna, fikk poteter.`,en:`It was a dry year. Those who watered got potatoes.`},wet:{no:`Det var et vått år. Tørråten hadde gode dager.`,en:`It was a wet year. The blight had good days.`},even:{no:`Det var et greit år. Da er det ikke været som har skylda.`,en:`It was a fair year. So the weather is not to blame.`}},tips:{plant:{no:`Sett noe. Jorda venter ikke.`,en:`Plant something. The soil will not wait.`},top:{no:`{row}: riset er sykt. Kutt det, ellers går råten ned i knollene.`,en:`{row}: the tops are sick. Cut them, or the rot goes down to the tubers.`},pick:{no:`{row}: brune flekker på bladene. Plukk dem nå, mens de er få.`,en:`{row}: brown spots on the leaves. Pick them now, while they are few.`},water:{no:`{row} er tørr. Vann den.`,en:`{row} is dry. Water it.`},lift:{no:`{row} er ferdig. Skallet sitter. Ta den opp.`,en:`{row} is done. The skin has set. Lift it.`},wait_skin:{no:`{row}: riset har visna. Vent to uker, så sitter skallet.`,en:`{row}: the tops have died back. Wait two weeks and the skin will set.`},frost:{no:`{row}: det er meldt frost. Spirene trenger duk.`,en:`{row}: frost is forecast. The sprouts need a fleece.`},hill:{no:`{row}: hypp nå. Når riset lukker radene, er det for sent.`,en:`{row}: hill now. Once the tops close the rows, it is too late.`},weed:{no:`{row}: luk. Ugresset tar det poteten skulle hatt.`,en:`{row}: weed it. The weeds take what the potato should have had.`},unfleece:{no:`{row}: ta av duken. Ugresset trives under den.`,en:`{row}: take the fleece off. The weeds thrive under it.`},calm:{no:`Ingenting haster. Poteten gjør jobben selv nå.`,en:`Nothing is urgent. The potato does the work itself now.`}},bye:{no:`Teigen står her neste år også.`,en:`The plot will be here next year too.`}},eeli:{ride:[{no:`Jeg hører på de samme ti sangene. Si fra hvis du blir gal.`,en:`I play the same ten songs. Say so if it drives you mad.`},{no:`Pappa spør hver dag om du har vært og sett til teigen. Han sier ikke at han spør.`,en:`Dad asks every day whether you have been to look at the plot. He does not say that he asks.`},{no:`Jeg tok bilde av raden din i går. Med linjal. Gammel vane.`,en:`I took a picture of your row yesterday. With a ruler. Old habit.`},{no:`Femti minutter hver vei. Jeg har regna på det. Det blir en uke i året i denne bilen.`,en:`Fifty minutes each way. I did the sums. That is a week a year in this car.`},{no:`Aino sier vi burde prøve nye sorter. Pappa sier vi skal se hva været sier.`,en:`Aino says we should try new varieties. Dad says we will see what the weather says.`},{no:`Det kommer an på åkeren. Det gjør alltid det.`,en:`It depends on the field. It always does.`},{no:`Naboen har slutta med poteter. Nå er det bare gress der.`,en:`The neighbour has stopped growing potatoes. It is all grass there now.`},{no:`Jorda sier sannheten. Bare ta en neve og kjenn.`,en:`Soil tells the truth. Just take a handful and feel.`}],alerts:{frost:{ask:{no:`Det er meldt nattefrost, og spirene dine står bare. Skal jeg legge jord over dem i kveld?`,en:`Night frost is forecast, and your sprouts are bare. Shall I pull soil over them tonight?`},yes:{no:`Gjort. De ser ut som små gravhauger, men de lever.`,en:`Done. They look like small burial mounds, but they are alive.`}},dry:{ask:{no:`Jorda i teigen din er tørr langt ned. Skal jeg vanne?`,en:`The soil in your plot is dry a long way down. Shall I water?`},yes:{no:`Jeg vanna litt på vei til hockeytreninga. Ikke like grundig som du gjør.`,en:`I watered a bit on my way to hockey practice. Not as thoroughly as you do.`}},blight:{ask:{no:`Unnskyld, jeg la bare merke til én ting. Brune flekker på riset ditt. Tørråte. Skal jeg plukke de syke bladene?`,en:`Sorry, I just noticed one thing. Brown spots on your tops. Blight. Shall I pick off the sick leaves?`},yes:{no:`Jeg plukka det jeg så. Det verste tok jeg helt ned.`,en:`I picked what I saw. The worst I took right down.`}},ripe:{ask:{no:`Riset har visna hos deg. Pappa kjører opptakeren i morgen. Skal jeg ta dine rader med?`,en:`Your tops have died back. Dad runs the harvester tomorrow. Shall I take your rows too?`},yes:{no:`De står i kasser på låven. Maskinen er litt hardhendt, bare så du vet det.`,en:`They are in crates in the barn. The machine is a bit rough, just so you know.`}}},last:{no:`Pappa pløyer i morgen. Jeg tok opp det som sto igjen med maskinen.`,en:`Dad ploughs tomorrow. I lifted what was left with the machine.`}}},de=.45,fe=.8,pe=1/15,me=9,he=40,ge=250,_e=864e5,_=(e,t=0,n=1)=>Math.min(n,Math.max(t,e)),ve=.88,ye=e=>e>.8?.8+(e-.8)*.5:e,be=e=>e.toISOString().slice(0,10),v=(e,t)=>e.varieties.find(e=>e.id===t)??e.varieties[0];function xe(e,t){let[n,r,i]=e.start.split(`-`).map(Number);return new Date(Date.UTC(n,r-1,i)+t*7*_e)}function Se(e,t,n){let r=be(xe(e,n)),i=[1,2,3,4,5,6,7].map(n=>c(e,t,`plot`,n,{date:r}));return{wet:i.filter(e=>e.weather===`rain`||e.weather===`storm`).length,sun:i.filter(e=>e.weather===`clear`).length,storm:i.some(e=>e.weather===`storm`),temp:Math.round(i.reduce((e,t)=>e+t.temp,0)/7*10)/10,frost:i.some(e=>e.weather===`clear`&&e.temp<=7)}}function Ce(e,t,r,i){let a=Se(e,t,r),o=i<=1?.2:.4;return n(`${t}:${r}:forecast:${i}`)>=o?a:Se(e,t*31+1e3+i,r)}var we=e=>e.w